import duckdb,boto3,json
cr=boto3.Session(profile_name='scrapivo').get_credentials().get_frozen_credentials(); c=duckdb.connect(); c.execute('LOAD httpfs'); c.execute("SET s3_region='us-east-2'"); c.execute("SET s3_access_key_id=?",[cr.access_key]); c.execute("SET s3_secret_access_key=?",[cr.secret_key]);
if cr.token:c.execute("SET s3_session_token=?",[cr.token])
c.execute("create view d as select * from read_parquet('s3://scrapivo-raw-data-2026-523220341033-us-east-2-an/processed/people_by_country/*/*.parquet',union_by_name=true,hive_partitioning=true)")
q="""select count(*) total,count(distinct country) countries,count(distinct city) cities,count(distinct title) titles,count(distinct industry) industries,sum((company_name is not null and trim(company_name)<>'')::int) company,sum((website is not null and trim(website)<>'')::int) website,sum((email is not null and trim(email)<>'')::int) email,sum((phone is not null and trim(phone)<>'')::int) phone,sum(((personal_linkedin is not null and trim(personal_linkedin)<>'') or (company_linkedin is not null and trim(company_linkedin)<>''))::int) linkedin,sum(((facebook is not null and trim(facebook)<>'') or (twitter is not null and trim(twitter)<>''))::int) other_social,sum(((website is not null and trim(website)<>'') or (email is not null and trim(email)<>'') or (phone is not null and trim(phone)<>'') or (personal_linkedin is not null and trim(personal_linkedin)<>'') or (company_linkedin is not null and trim(company_linkedin)<>'') or (facebook is not null and trim(facebook)<>'') or (twitter is not null and trim(twitter)<>''))::int) any_contact,count(case when personal_linkedin is not null and trim(personal_linkedin)<>'' then 1 end)-count(distinct case when personal_linkedin is not null and trim(personal_linkedin)<>'' then personal_linkedin end) duplicate_linkedin_extra,count(case when website is not null and trim(website)<>'' then 1 end)-count(distinct case when website is not null and trim(website)<>'' then website end) duplicate_website_extra from d"""
r=c.execute(q); out=dict(zip([x[0] for x in r.description],r.fetchone())); out['top_countries']=c.execute("select country,count(*) n from d group by country order by n desc limit 25").fetchall(); out['top_titles']=c.execute("select title,count(*) n from d group by title order by n desc limit 30").fetchall(); out['top_industries']=c.execute("select industry,count(*) n from d group by industry order by n desc limit 20").fetchall();
open('reports/gate2/_people-profile.json','w').write(json.dumps(out,indent=2,default=str)); print('done')